import { Component, OnInit, ChangeDetectionStrategy, NgZone, ChangeDetectorRef } from '@angular/core';
import { delayBetween, DestroySubject, getUtcNow } from '@honoregaming/core';
import { Subscription, timer } from 'rxjs';
import { takeUntil } from 'rxjs/operators';
import { DrawGamesService } from '@honoregaming/draw-games-ui';

@Component({
  selector: 'hg-draw-games-page-header',
  templateUrl: './draw-games-page-header.component.html',
  styleUrls: ['./draw-games-page-header.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DrawGamesPageHeaderComponent extends DestroySubject implements OnInit {
  countDown: number;
  timerCountDown: Subscription;
  nextDrawGameDates: Date[] = [];
  nextSingleDrawGameDate?: Date;
  displayNextDate: boolean = false;

  constructor(private zone: NgZone, private cdRef: ChangeDetectorRef, private drawGamesService: DrawGamesService) {
    super();
  }

  ngOnInit(): void {
    this.timerCountDown = timer(0, 1000)
      .pipe(takeUntil(this.destroy$))
      .subscribe(_ => {
        let nextDate =
          this.nextSingleDrawGameDate ?? (this.nextDrawGameDates.length > 0 ? this.nextDrawGameDates[0] : undefined);
        if (nextDate) {
          const delay = delayBetween(getUtcNow(), nextDate);
          if (delay <= 0) {
            if (this.nextSingleDrawGameDate) {
              this.countDown = 0;
            } else {
              this.nextDrawGameDates = this.nextDrawGameDates.slice(1);
              nextDate = undefined;
            }
          } else {
            this.countDown = delay;
          }

          this.zone.run(() => this.cdRef.markForCheck());
        }

        this.displayNextDate = nextDate != null;
      });

    this.drawGamesService.$nextDrawGamesDatesEvent.pipe(takeUntil(this.destroy$)).subscribe(dates => {
      if (dates && dates.length > 0) {
        this.nextDrawGameDates = dates;
      }

      this.nextSingleDrawGameDate = undefined;
      this.cdRef.markForCheck();
    });

    this.drawGamesService.$nextSingleDrawGameDateEvent.pipe(takeUntil(this.destroy$)).subscribe(date => {
      this.nextSingleDrawGameDate = date;
      this.cdRef.markForCheck();
    });
  }
}
