import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'hg-draw-game-multiple-flash',
  templateUrl: './multiple-flash.component.html',
  styleUrls: ['./multiple-flash.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DrawGameMultipleFlashComponent {
  @Input()
  multipleFlashNumbers: number[] = [];

  @Output()
  close = new EventEmitter();

  flash(multiple: number) {
    this.close.emit({ flashNumber: multiple });
  }
}
