import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, OnInit } from '@angular/core';
import { DestroySubject, getDaysRange, getStartEndDayDate, EnrichDrawGame } from '@honoregaming/core';
import { DrawGame } from '@honoregaming/types';
import { EventsService } from '@honoregaming/events';
import { takeUntil, finalize } from 'rxjs/operators';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';

@Component({
  selector: 'hg-draw-games-results',
  templateUrl: './results.component.html',
  styleUrls: ['./results.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DrawGameResultsComponent extends DestroySubject implements OnInit {
  static DAYS_NUMBER_THRESHOLD: number = 7;
  firstLoading = true;
  lockLoading = true;
  loading = false;
  error = false;
  events: DrawGame[] = [];
  dateSelected: Date;
  dates: Date[] = [];
  selectedDateIndex = 0;
  displayCalendar: boolean = false;
  calendarSelectedDate: string | undefined;
  minDate: string;
  maxDate: string;

  constructor(
    private eventsService: EventsService,
    protected cdRef: ChangeDetectorRef,
    @Inject(operatorConfigurationToken) public operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  ngOnInit() {
    const daysNumber: number =
      this.operatorConfiguration?.drawGameConfiguration?.customerDaysOfDrawGamesResults >= 1
        ? this.operatorConfiguration.drawGameConfiguration.customerDaysOfDrawGamesResults
        : DrawGameResultsComponent.DAYS_NUMBER_THRESHOLD;
    this.displayCalendar = daysNumber > DrawGameResultsComponent.DAYS_NUMBER_THRESHOLD;
    const firstDate = new Date();
    firstDate.setDate(firstDate.getDate() - daysNumber + 1);
    this.minDate = this.formatDate(firstDate);
    this.maxDate = this.formatDate(new Date());
    if (this.displayCalendar) {
      this.calendarSelectedDate = this.maxDate;
      this.dateSelected = this.getDateFromString(this.calendarSelectedDate);
    } else {
      this.dates = getDaysRange(0, daysNumber - 1);
      this.dateSelected = this.dates[this.selectedDateIndex];
    }

    this.firstLoading = true;
    this.loadEvents();
  }

  loadEvents() {
    const { start: from, end: to } = getStartEndDayDate(this.dateSelected);
    this.loading = true;
    this.eventsService
      .getDrawGamesResults<DrawGame>(from, to, this.firstLoading)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.firstLoading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        results => {
          // Get selection with or without extra to display extra numbers differently
          const newEvents = results.result.map(event => {
            const result = event.result.split(' ');
            if (result.indexOf('E') > -1) {
              event.baseSelection = result.slice(1, result.indexOf('E'));
              event.extraSelection = result.slice(result.indexOf('E') + 1, result.length);
            } else {
              event.baseSelection = result.slice(1, result.length);
            }
            EnrichDrawGame(event);
            return event;
          });
          this.events = newEvents;
          if (this.firstLoading) {
            if (this.events?.length > 0) {
              if (this.displayCalendar) {
                const foundDate = new Date(this.events[0].expectedStart);
                if (
                  foundDate >= this.getDateFromString(this.minDate) &&
                  foundDate <= this.getDateFromString(this.maxDate)
                ) {
                  this.calendarSelectedDate = this.formatDate(foundDate);
                }
              } else {
                var i = 0;
                while (new Date(this.events[0].expectedStart) < new Date(this.dates[i])) {
                  this.dateSelected = this.dates[i];
                  i++;
                }
              }
            }
          }
        },
        _error => {
          this.error = true;
        }
      );
  }

  onDateChange() {
    if (!this.firstLoading) {
      this.lockLoading = false;
    }

    if (this.displayCalendar) {
      this.dateSelected = this.getDateFromString(this.calendarSelectedDate);
    }

    if (
      this.dateSelected &&
      !this.firstLoading &&
      !this.lockLoading &&
      this.dateSelected >= this.getDateFromString(this.minDate) &&
      this.dateSelected <= this.getDateFromString(this.maxDate)
    ) {
      this.refreshDestroySubject();
      this.events = [];
      this.loadEvents();
    }
  }

  getDateFromString(date: string): Date {
    const [year, month, day] = date.split('-').map(Number);
    const result = new Date(year, month - 1, day);
    return result;
  }

  formatDate(date: Date): string {
    return (
      date.getFullYear() +
      '-' +
      String(date.getMonth() + 1).padStart(2, '0') +
      '-' +
      String(date.getDate()).padStart(2, '0')
    );
  }
}
