import { Component, OnInit, ChangeDetectionStrategy, PLATFORM_ID, Inject } from '@angular/core';
import { Router } from '@angular/router';
import { isPlatformServer } from '@angular/common';
import { takeUntil } from 'rxjs/operators';
import { BetSlipService } from '@honoregaming/betslip';
import { DestroySubject } from '@honoregaming/core';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { BetCategoryType } from '@honoregaming/types';

@Component({
  selector: 'hg-layout',
  templateUrl: './layout.component.html',
  styleUrls: ['./layout.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LayoutComponent extends DestroySubject implements OnInit {
  isServer = isPlatformServer(this.platformId);
  displayBanner: boolean = false;
  displayBorlettePage: boolean = false;

  constructor(
    private router: Router,
    private betSlipService: BetSlipService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    @Inject(PLATFORM_ID) private platformId
  ) {
    super();
  }

  ngOnInit(): void {
    this.betSlipService.changeCurrentBetCategory(BetCategoryType.DrawGame);
    this.displayBorlettePage = this.operatorConfiguration?.onlineConfiguration?.displayBorlettePage ?? false;
    this.updateDisplayBanner();
    this.router.events.pipe(takeUntil(this.destroy$)).subscribe(_ => {
      this.updateDisplayBanner();
    });
  }

  navigated(eventCategoryId: number): void {
    this.router.navigate(['/draw-games', eventCategoryId]);
  }

  private updateDisplayBanner(): void {
    const relativeUrl: string = this.router.url.split('?')[0];
    this.displayBanner = relativeUrl === '/draw-games';
  }
}
