import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, Input, OnChanges, OnInit } from '@angular/core';
import { DrawGameBetSlipService } from '@honoregaming/betslip';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { DestroySubject } from '@honoregaming/core';
import { TelemetryService } from '@honoregaming/customer-core';
import { DrawGame } from '@honoregaming/types';
import { takeUntil } from 'rxjs/operators';
@Component({
  selector: 'hg-draw-games-event-preview',
  templateUrl: './event-preview.component.html',
  styleUrls: ['./event-preview.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DrawGamesEventPreviewComponent extends DestroySubject implements OnInit, OnChanges {
  @Input() event: DrawGame;
  @Input() drawGames: DrawGame[];
  canReplay: boolean = false;

  constructor(
    private drawGameBetSlipService: DrawGameBetSlipService,
    private cdRef: ChangeDetectorRef,
    private telemetryService: TelemetryService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    this.drawGameBetSlipService.$drawGameBetPlaced
      .pipe(takeUntil(this.destroy$))
      .subscribe(_ => this.updateCanReplay());
  }

  ngOnChanges(): void {
    this.updateCanReplay();
  }

  updateCanReplay(): void {
    this.canReplay = this.drawGameBetSlipService.canReplayEvent(
      this.event,
      this.operatorConfiguration?.drawGameConfiguration?.allowsCustomerToReplayLastDrawGameSelection,
      this.drawGames
    );
    this.cdRef.markForCheck();
  }

  replay(): void {
    this.telemetryService.trackEvent('replay_draw_game');
    this.drawGameBetSlipService.replayEvent(
      this.event,
      this.operatorConfiguration?.drawGameConfiguration?.allowsCustomerToReplayLastDrawGameSelection
    );
  }
}
