import { Component, ChangeDetectionStrategy, EventEmitter, Input, Output } from '@angular/core';
import { EventBetType, DrawGameBorletteBetType } from '@honoregaming/types';

@Component({
  selector: 'hg-draw-game-borlette-item',
  templateUrl: './draw-game-borlette-item.component.html',
  styleUrls: ['./draw-game-borlette-item.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DrawGameBorletteItemComponent {
  @Input() selectedDrawGame: EventBetType;
  @Input() item: { number: number; stake: number; selected: boolean; error: { stake: boolean | string } };
  @Input() index: number;
  @Input() selection: any[];
  @Input() padLength: number;
  @Input() predefinedStakes: number[];
  @Input() modal: boolean = false;
  @Input() indexItemFocused: number = 0;

  DrawGameBorletteBetType = DrawGameBorletteBetType;

  @Output()
  changeInputNumberEvent = new EventEmitter();

  @Output()
  changeInputNumbersEvent = new EventEmitter();

  @Output()
  decrementStakeEvent = new EventEmitter();

  @Output()
  incrementStakeEvent = new EventEmitter();

  @Output()
  changeStakeEvent = new EventEmitter();

  @Output()
  decrementStakeOptionsEvent = new EventEmitter();

  @Output()
  incrementStakeOptionsEvent = new EventEmitter();

  @Output()
  changeStakeOptionsEvent = new EventEmitter();

  @Output()
  removeEvent = new EventEmitter();

  @Output()
  resetStakeEvent = new EventEmitter();

  @Output()
  setStakeEvent = new EventEmitter();

  @Output()
  focusEvent = new EventEmitter();

  @Output()
  selectEvent = new EventEmitter();

  @Output()
  selectOptionsEvent = new EventEmitter();

  constructor() {}

  checkNumber(event: Event): string {
    const input = event.target as HTMLInputElement;
    let result = input.value;
    if (input.value) {
      const value = Number(input.value).toString();
      let match = value.match(new RegExp(`\\d{1,${this.padLength}}`));
      result = match ? match[0] : null;
    }

    input.value = result;
    return result;
  }

  selectItem() {
    if (!this.item.stake) {
      return;
    }

    this.selectEvent.emit();
  }

  updateNumber(event: Event): void {
    this.selection[this.index].number = this.checkNumber(event);
    this.changeInputNumberEvent.emit(this.selection[this.index].number);
  }

  updateNumbers(event: Event, numbersIndex: string): void {
    this.selection[this.index].numbers[numbersIndex] = this.checkNumber(event);
    this.changeInputNumbersEvent.emit({
      index: this.index,
      numbersIndex: numbersIndex,
      value: this.selection[this.index].numbers[numbersIndex]
    });
  }
}
