import { Component, ChangeDetectionStrategy, OnInit, ChangeDetectorRef, Inject } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { DrawGame, DrawGameBorletteBetType, TopEventsByDrawGame } from '@honoregaming/types';
import { finalize, switchMap, takeUntil } from 'rxjs/operators';
import { EventsService } from '@honoregaming/events';
import { BroadcastingService, DestroySubject, getUtcNow } from '@honoregaming/core';
import { EMPTY } from 'rxjs';
import { ContentService } from '@honoregaming/templating';
import { DrawGameBorletteModalComponent } from '../../components/draw-games/draw-game-borlette/draw-game-borlette-modal/draw-game-borlette-modal.component';
import { MessageService } from '@honoregaming/ui';
import { TitleModal } from '../../components/draw-games/draw-game-borlette/draw-game-borlette.component';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { DrawGameBetSlipService } from '@honoregaming/betslip';
import { DrawGamesService } from '@honoregaming/draw-games-ui';
import { TelemetryService } from '@honoregaming/customer-core';

@Component({
  selector: 'hg-draw-game',
  templateUrl: './draw-game.component.html',
  styleUrls: ['./draw-game.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DrawGameComponent extends DestroySubject implements OnInit {
  drawGame?: DrawGame;
  isEmptyBorlette: boolean = false;

  loading: boolean;
  error: boolean;
  isEventPage: boolean = false;

  toggleRules = false;
  ruleTypeContent: string;
  ruleTypeStyle: string;

  canReplay: boolean = false;
  canReplayEvent: boolean = false;
  displayPointe: boolean = false;
  displayRaleBoule: boolean = false;

  drawGames: DrawGame[] = [];

  constructor(
    private route: ActivatedRoute,
    private cdRef: ChangeDetectorRef,
    private eventsService: EventsService,
    private contentService: ContentService,
    private broadcastingService: BroadcastingService,
    private messageService: MessageService,
    private drawGameBetSlipService: DrawGameBetSlipService,
    private drawGamesService: DrawGamesService,
    private telemetryService: TelemetryService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  ngOnInit() {
    this.loading = true;
    this.error = false;

    this.eventsService
      .getNextDrawGamesEvents()
      .pipe(
        takeUntil(this.destroy$),
        switchMap(events => {
          this.setEvents(events);
          if (this.drawGames.length > 0) {
            const urlSegments = this.route.snapshot.url.map(s => s.path);
            if (urlSegments[urlSegments.length - 1] === 'borlette') {
              this.isEmptyBorlette = true;
              return EMPTY;
            } else {
              return this.route.params.pipe(takeUntil(this.destroy$));
            }
          } else {
            this.error = true;
          }
        }),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        params => {
          if (params.eventId) {
            this.isEventPage = true;
            const eventId = +params.eventId;
            const cachedEvent = this.eventsService.getEventFromCache<DrawGame>(eventId);
            if (!cachedEvent || !cachedEvent.eventBetTypes) {
              this.eventsService
                .getEventDetails(eventId)
                .pipe(
                  takeUntil(this.destroy$),
                  finalize(() => {
                    this.loading = false;
                    this.updateCanReplay();
                    this.cdRef.markForCheck();
                  })
                )
                .subscribe((event: DrawGame) => {
                  if (event?.drawGameRule && event.eventBetTypes && getUtcNow() < new Date(event.expectedStart)) {
                    this.setEvent(event);
                  } else {
                    this.error = true;
                  }
                });
            } else {
              this.loading = false;
              this.setEvent(cachedEvent);
            }
          } else {
            this.error = true;
          }
        },
        _error => {
          this.error = true;
        }
      );

    this.broadcastingService
      .register('BorletteModal')
      .pipe(
        switchMap((args: { type: string; numbers: string[] }) => {
          return this.messageService.sendComponentMessage(
            DrawGameBorletteModalComponent,
            {
              selectedDrawGame: this.drawGame.eventBetTypes.find(
                x => x.betTypeId === DrawGameBorletteBetType[args.type]
              ),
              titleModal:
                args.type === DrawGameBorletteBetType[DrawGameBorletteBetType.Loto4]
                  ? TitleModal.Loto4
                  : TitleModal.Mariage,
              predefinedStakes: this.operatorConfiguration.global.predefinedStakes
                ?.drawGameFixedOddsPredefinedStakes ?? [50, 100, 250],
              numbers: args.numbers,
              event: this.drawGame
            },
            {
              canBeDismissed: true,
              displayClose: false,
              className: 'draw-game-borlette-modal'
            }
          ).closed;
        }),
        takeUntil(this.destroy$)
      )
      .subscribe();

    this.updateCanReplay();

    this.drawGameBetSlipService.$drawGameBetPlaced
      .pipe(takeUntil(this.destroy$))
      .subscribe(_ => this.updateCanReplay());

    this.displayPointe = this.operatorConfiguration?.onlineConfiguration?.displayBorlettePointeToolOnCustomer ?? false;
    this.displayRaleBoule =
      this.operatorConfiguration?.onlineConfiguration?.displayBorletteRaleBouleToolOnCustomer ?? false;
  }

  setEvents(events: TopEventsByDrawGame[]): void {
    this.drawGames = this.drawGamesService.filterAndSortDrawGames(events);

    if (!this.drawGame) {
      this.drawGamesService.displayNextDrawGamesDates(this.drawGames?.map(x => x.expectedStart));
    }
  }

  setEvent(drawGame: DrawGame) {
    this.drawGame = drawGame;
    this.drawGamesService.displayNextSingleDrawGameDate(this.drawGame.expectedStart);
    this.contentService
      .getContent('draw-games-rules-' + drawGame.drawGameRule.type)
      .pipe(takeUntil(this.destroy$))
      .subscribe(resource => {
        this.ruleTypeContent = resource.content;
        this.ruleTypeStyle = resource.style;
      });
  }

  updateCanReplay(): void {
    this.canReplay = this.drawGameBetSlipService.canReplay(
      this.operatorConfiguration?.drawGameConfiguration?.allowsCustomerToReplayLastDrawGameSelection
    );
    this.canReplayEvent =
      this.drawGame &&
      this.drawGameBetSlipService.canReplayEvent(
        this.drawGame,
        this.operatorConfiguration?.drawGameConfiguration?.allowsCustomerToReplayLastDrawGameSelection,
        this.drawGames
      );
    this.cdRef.markForCheck();
  }

  replay(): void {
    this.telemetryService.trackEvent('replay_draw_game');
    this.drawGameBetSlipService.replay(
      this.operatorConfiguration?.drawGameConfiguration?.allowsCustomerToReplayLastDrawGameSelection
    );
  }

  replayEvent(): void {
    this.drawGameBetSlipService.replayEvent(
      this.drawGame,
      this.operatorConfiguration?.drawGameConfiguration?.allowsCustomerToReplayLastDrawGameSelection
    );
  }
}
