import {
  Component,
  ChangeDetectorRef,
  OnInit,
  ChangeDetectionStrategy,
  Inject,
  Input,
  PLATFORM_ID
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { BroadcastingService, DestroySubject, Scope, scopeToken, add, sub, mod } from '@honoregaming/core';
import { DrawGame, DrawGameBorletteBetType } from '@honoregaming/types';
import { BetCategoryType, DrawGameDetails, EventBetType } from '@honoregaming/types';
import { BetLine, BetSlipService, createBetLineWithSelection } from '@honoregaming/betslip';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { MessageService } from '@honoregaming/ui';
import { TchalaComponent } from '../../../containers/tchala/tchala.component';
import { takeUntil } from 'rxjs/operators';
import {
  DrawGamesService,
  RecommendedNumbersSelectionToolComponent,
  RecommendedNumbersSelectionToolProperties,
  SimpleNumbersSelectionToolComponent,
  SimpleNumbersSelectionToolProperties,
  TableNumbersSelectionToolComponent,
  TableNumbersSelectionToolProperties
} from '@honoregaming/draw-games-ui';
import { I18nService } from '@honoregaming/i18n';

const DEFAULT_NUMBER_OBJECT = {
  number: null,
  stake: null,
  error: {
    number: false,
    stake: false
  },
  numbers: {
    first: null,
    second: null,
    third: null
  },
  options: {
    '1': {
      stake: null,
      selected: false,
      error: null
    },
    '2': {
      stake: null,
      selected: false,
      error: null
    },
    '3': {
      stake: null,
      selected: false,
      error: null
    }
  }
};

@Component({
  selector: 'hg-draw-game-borlette',
  templateUrl: './draw-game-borlette.component.html',
  styleUrls: ['./draw-game-borlette.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DrawGameBorletteComponent extends DestroySubject implements OnInit {
  @Input() event: DrawGame;

  drawGamesList: EventBetType[];
  selectedDrawGame: EventBetType;
  selection: any[] = [JSON.parse(JSON.stringify(DEFAULT_NUMBER_OBJECT))];
  selectionIsValid: boolean = false;
  totalStake: number = 0;
  padLength: number = 2;
  predefinedStakes: number[];
  timer: any;
  displayModal: boolean = false;
  selectionModal: any[];
  selectedDrawGameModal: EventBetType;
  titleModal: TitleModal = TitleModal.Twins;
  borletteNumbers: string[] = [];
  indexItemFocused: number;
  DrawGameBorletteBetType = DrawGameBorletteBetType;
  displayPointe: boolean = false;
  displayRaleBoule: boolean = false;

  constructor(
    private betSlipService: BetSlipService,
    private cdRef: ChangeDetectorRef,
    private broadcastingService: BroadcastingService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    @Inject(PLATFORM_ID) private platformId,
    @Inject(scopeToken) public userScope: Scope,
    private messageService: MessageService,
    private i18nService: I18nService,
    private drawGamesService: DrawGamesService
  ) {
    super();
    this.setPredefinedSkates();
  }

  ngOnInit(): void {
    this.drawGamesList = this.event.eventBetTypes;
    this.drawGamesList.sort((a, b) => a.name.localeCompare(b.name, 'en', { sensitivity: 'base' }));
    for (let i = 0; i < this.drawGamesList.length; i++) {
      if (this.drawGamesList[i].active) {
        this.selectedDrawGame = this.drawGamesList[i];

        if (this.selection?.length) {
          this.selection[0].stake = this.getDefaultStake();
        }

        break;
      }
    }

    this.broadcastingService.register('BorletteModal').subscribe((args: { type: string; numbers: string[] }) => {
      this.borletteNumbers = args.numbers;
      this.openAutoModal(DrawGameBorletteBetType[args.type]);
    });

    this.displayPointe = this.operatorConfiguration?.onlineConfiguration?.displayBorlettePointeToolOnCustomer ?? false;
    this.displayRaleBoule =
      this.operatorConfiguration?.onlineConfiguration?.displayBorletteRaleBouleToolOnCustomer ?? false;
  }

  openBoulePe(): void {
    this.displayTool(SimpleNumbersSelectionToolComponent, {
      title: this.i18nService.translateSync('DRAW_GAMES.BORLETTE.LABEL.TWIN_NUMBERS'),
      numbers: this.drawGamesService.getBorletteTwinNumbers(),
      disabledNumbers: this.selection?.map(item => this.formatNumber(item.number)),
      showSelectAll: true
    });
  }

  openPointe(): void {
    this.displayTool(TableNumbersSelectionToolComponent, {
      title: this.i18nService.translateSync('DRAW_GAMES.BORLETTE.LABEL.POINTE'),
      numbers: this.drawGamesService.getBorlettePointeNumbers(),
      disabledNumbers: this.selection?.map(item => this.formatNumber(item.number)),
      showSelectAll: false,
      keyColumnName: this.i18nService.translateSync('DRAW_GAMES.BORLETTE.LABEL.POINTE'),
      displaySearch: false,
      homogeneousColumnWidth: false,
      searchPlaceholder: ''
    });
  }

  openTchala(): void {
    this.displayTool(TableNumbersSelectionToolComponent, {
      title: this.i18nService.translateSync('DRAW_GAMES.BORLETTE.LABEL.TCHALA'),
      numbers: this.drawGamesService.getBorletteTchalaNumbers(),
      disabledNumbers: this.selection?.map(item => this.formatNumber(item.number)),
      showSelectAll: false,
      keyColumnName: this.i18nService.translateSync('DRAW_GAMES.BORLETTE.LABEL.REV'),
      displaySearch: true,
      homogeneousColumnWidth: true,
      searchPlaceholder: this.i18nService.translateSync('TCHALA.SEARCH')
    });
  }

  openRaleBoule(): void {
    this.displayTool(RecommendedNumbersSelectionToolComponent, {
      title: this.i18nService.translateSync('DRAW_GAMES.LABEL.RECOMMENDEDNUMBERS'),
      searchPlaceholder: this.i18nService.translateSync('DRAW_GAMES.LABEL.ENTERNUMBER'),
      defaultSearchNumber: +this.selection?.filter(x => x.number != null).slice(-1)[0]?.number,
      disabledNumbers: this.selection?.map(item => this.formatNumber(item.number)),
      showSelectAll: true,
      betTypeId: this.selectedDrawGame.betTypeId,
      drawGameRuleIds: [],
      recommendedNumbersCount: 4,
      formatNumber: this.formatNumber
    });
  }

  displayTool(
    component: any,
    properties:
      | SimpleNumbersSelectionToolProperties
      | TableNumbersSelectionToolProperties
      | RecommendedNumbersSelectionToolProperties
  ): void {
    this.messageService
      .sendComponentMessage(component, properties, {
        canBeDismissed: true,
        displayClose: true,
        className: 'draw-game-tool'
      })
      .closed.pipe(takeUntil(this.destroy$))
      .subscribe((numbers: number[] | undefined) => {
        if (numbers) {
          for (const number of numbers) {
            if (!this.selection.some(item => item.number != null && item.number !== '' && +item.number === +number)) {
              const emptyIndex = this.selection.findIndex(x => x.number == null || x.number === '');
              if (emptyIndex >= 0) {
                this.selection[emptyIndex].number = number;
                this.selection = [...this.selection];
              } else {
                const defaultObject = JSON.parse(JSON.stringify(DEFAULT_NUMBER_OBJECT));
                defaultObject.number = number;
                this.setDefaultStake(defaultObject);
                this.selection.push(defaultObject);
              }
            }
          }

          this.isSelectionValid();
        }
      });
  }

  selectGame(index: number): void {
    this.selectedDrawGame = this.drawGamesList[index];
    this.setPredefinedSkates();

    this.event.drawGameRule.drawGameDetails.forEach((drawGameDetail: DrawGameDetails) => {
      if (drawGameDetail.betTypeId === this.selectedDrawGame.betTypeId) {
        this.padLength =
          this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Mariage
            ? 2
            : drawGameDetail.maxBaseNumber.toString().length;
      }
    });
    this.resetSelection();
  }

  setPredefinedSkates(): void {
    this.predefinedStakes =
      this.selectedDrawGame?.betTypeId === DrawGameBorletteBetType.Loto6
        ? [10, 25, 50]
        : this.operatorConfiguration.global.predefinedStakes?.drawGameFixedOddsPredefinedStakes
        ? this.operatorConfiguration.global.predefinedStakes?.drawGameFixedOddsPredefinedStakes
        : [50, 100, 250];
  }

  resetSelection() {
    let defaultObject = JSON.parse(JSON.stringify(DEFAULT_NUMBER_OBJECT));
    this.setDefaultStake(defaultObject);
    this.selection = [defaultObject];
    this.isSelectionValid();
  }

  setDefaultStake(defaultObject: any) {
    defaultObject.stake = this.getDefaultStake();
  }

  removeItem(index: number): void {
    this.selection.splice(index, 1);
    this.computeTotalStake();
    this.isSelectionValid();
  }

  setStakeItem(amount: number, index: number): void {
    if (
      this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto4 ||
      this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto5
    ) {
      this.selection[index].options['1'].stake = amount;
      this.selection[index].options['1'].selected = true;
      this.selection[index].options['2'].stake = amount;
      this.selection[index].options['2'].selected = true;
      this.selection[index].options['3'].stake = amount;
      this.selection[index].options['3'].selected = true;
    } else {
      this.selection[index].stake = amount;
    }
    this.computeTotalStake();
    this.isSelectionValid();
    this.selection[index].error.stake = false;
  }

  resetStake(index: number): void {
    if (
      this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto4 ||
      this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto5
    ) {
      Object.entries(this.selection[index].options).forEach((option: any) => {
        option[1].stake = null;
        option[1].selected = false;
      });
    } else {
      this.selection[index].stake = null;
    }

    this.computeTotalStake();
    this.isSelectionValid();
  }

  addNumber(): void {
    let defaultObject = JSON.parse(JSON.stringify(DEFAULT_NUMBER_OBJECT));
    this.setDefaultStake(defaultObject);
    this.selection.push(defaultObject);
    this.isSelectionValid();
  }

  handleInputNumber(inputNumber: string, index: number) {
    this.selection[index].number = this.formatNumber(inputNumber);
    this.isSelectionValid();
    this.cdRef.markForCheck();
  }

  handleInputNumbers(data: { index: number; numbersIndex: number; value: string }) {
    this.selection[data.index].numbers[data.numbersIndex] = this.formatNumber(data.value);
    this.isSelectionValid();
    this.cdRef.markForCheck();
  }

  formatNumber(number: string): string {
    number = number?.toString();
    if (number && number.length > 0) {
      if (number.length > this.padLength && number.charAt(0) === '0') {
        number = number.slice(1);
      } else {
        number = number.padStart(this.padLength, '0');
      }
    }
    return number;
  }

  handleIncrement(index: number) {
    this.selection[index].stake = +this.selection[index].stake;
    if (!this.selection[index].stake) {
      this.selection[index].stake = this.getDefaultStake();
      this.computeTotalStake();
      this.isSelectionValid();
      this.selection[index].error.stake = false;
      return;
    }

    this.selection[index].stake = add(this.selection[index].stake, this.selectedDrawGame.minimumAmountIncrement);
    this.computeTotalStake();
    this.isSelectionValid();
    this.selection[index].error.stake = false;
  }

  handleIncrementOptions(index: number, optionsIndex: string) {
    this.selection[index].options[optionsIndex].stake = +this.selection[index].options[optionsIndex].stake;
    if (!this.selection[index].options[optionsIndex].stake) {
      this.selection[index].options[optionsIndex].stake = this.getDefaultStake();
      this.selection[index].options[optionsIndex].selected = true;
      this.computeTotalStake();
      this.isSelectionValid();
      this.selection[index].options[optionsIndex].error = false;
      return;
    }

    this.selection[index].options[optionsIndex].stake = add(
      this.selection[index].options[optionsIndex].stake,
      this.selectedDrawGame.minimumAmountIncrement
    );
    this.selection[index].options[optionsIndex].selected = true;
    this.computeTotalStake();
    this.isSelectionValid();
    this.selection[index].options[optionsIndex].error = false;
  }

  handleDecrement(index: number) {
    if (
      !this.selection[index].stake ||
      sub(this.selection[index].stake, this.selectedDrawGame.minimumAmountIncrement) < this.selectedDrawGame.baseAmount
    ) {
      this.selection[index].stake = this.selectedDrawGame.baseAmount;
      this.computeTotalStake();
      this.isSelectionValid();
      this.selection[index].error.stake = false;
      return;
    }

    if (this.selection[index].stake === this.selectedDrawGame.baseAmount) {
      return;
    }

    this.selection[index].stake = sub(this.selection[index].stake, this.selectedDrawGame.minimumAmountIncrement);
    this.computeTotalStake();
    this.selection[index].error.stake = false;
  }

  handleDecrementOptions(index: number, optionsIndex: string) {
    if (
      !this.selection[index].options[optionsIndex].stake ||
      sub(this.selection[index].options[optionsIndex].stake, this.selectedDrawGame.minimumAmountIncrement) <
        this.selectedDrawGame.baseAmount
    ) {
      this.selection[index].options[optionsIndex].stake = this.selectedDrawGame.baseAmount;
      this.selection[index].options[optionsIndex].selected = true;
      this.computeTotalStake();
      this.isSelectionValid();
      this.selection[index].options[optionsIndex].error = false;
      return;
    }

    if (this.selection[index].options[optionsIndex].stake === this.selectedDrawGame.baseAmount) {
      return;
    }

    this.selection[index].options[optionsIndex].stake = sub(
      this.selection[index].options[optionsIndex].stake,
      this.selectedDrawGame.minimumAmountIncrement
    );
    this.computeTotalStake();
    this.isSelectionValid();
    this.selection[index].options[optionsIndex].error = false;
  }

  handleStakeChange(value: number, index: number) {
    this.selection[index].stake = value;
    if (
      this.selection[index].stake !== null &&
      this.selection[index].stake.toString().length > 0 &&
      this.selection[index].stake < this.selectedDrawGame.baseAmount
    ) {
      this.selection[index].error.stake = 'baseAmount';
      this.isSelectionValid();
      this.computeTotalStake();
      return;
    }
    this.selection[index].error.stake = false;

    if (mod(this.selection[index].stake, this.selectedDrawGame.minimumAmountIncrement) !== 0) {
      this.selection[index].error.stake = 'minimumAmountIncrement';
    }
    this.isSelectionValid();
    this.computeTotalStake();
  }

  handleStakeOptionsChange(data: { index: number; optionsIndex: string; value: number }, index: number) {
    this.selection[index].options[data.optionsIndex].stake = data.value;
    if (
      this.selection[index].options[data.optionsIndex].stake !== null &&
      this.selection[index].options[data.optionsIndex].stake.toString().length > 0 &&
      parseInt(this.selection[index].options[data.optionsIndex].stake) < this.selectedDrawGame.baseAmount
    ) {
      this.selection[index].options[data.optionsIndex].error = 'baseAmount';
      this.selection[index].options[data.optionsIndex].selected = false;
      this.isSelectionValid();
      this.computeTotalStake();
      return;
    } else if (parseInt(this.selection[index].options[data.optionsIndex].stake) >= this.selectedDrawGame.baseAmount) {
      this.selection[index].options[data.optionsIndex].selected = true;
    } else {
      this.selection[index].options[data.optionsIndex].selected = false;
    }
    this.selection[index].options[data.optionsIndex].error = false;

    if (this.selection[index].options[data.optionsIndex].selected) {
      if (
        mod(this.selection[index].options[data.optionsIndex].stake, this.selectedDrawGame.minimumAmountIncrement) !== 0
      ) {
        this.selection[index].options[data.optionsIndex].error = 'minimumAmountIncrement';
      }
      this.isSelectionValid();
      this.computeTotalStake();
    } else {
      this.isSelectionValid();
      this.computeTotalStake();
    }
  }

  computeTotalStake(): void {
    this.totalStake = 0;

    this.selection.forEach(item => {
      if (
        this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto4 ||
        this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto5
      ) {
        this.totalStake = add(
          this.totalStake,
          item.options['1'].stake && item.options['1'].selected ? +item.options['1'].stake : 0
        );
        this.totalStake = add(
          this.totalStake,
          item.options['2'].stake && item.options['2'].selected ? +item.options['2'].stake : 0
        );
        this.totalStake = add(
          this.totalStake,
          item.options['3'].stake && item.options['3'].selected ? +item.options['3'].stake : 0
        );
      } else {
        if (item.stake) {
          this.totalStake = add(this.totalStake, +item.stake);
        }
      }
    });
  }

  isSelectionValid() {
    for (let i = 0; i < this.selection.length; i++) {
      const selection = this.selection[i];
      if (
        this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto4 ||
        this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto5
      ) {
        if (
          selection.number &&
          selection.number.length === this.padLength &&
          !Number.isNaN(parseInt(selection.number)) &&
          parseInt(selection.number) >= 0 &&
          ((selection.options['1'].stake &&
            !Number.isNaN(parseInt(selection.options['1'].stake)) &&
            parseInt(selection.options['1'].stake) >= this.selectedDrawGame.baseAmount) ||
            (selection.options['2'].stake &&
              !Number.isNaN(parseInt(selection.options['2'].stake)) &&
              parseInt(selection.options['2'].stake) >= this.selectedDrawGame.baseAmount) ||
            (selection.options['3'].stake &&
              !Number.isNaN(parseInt(selection.options['3'].stake)) &&
              parseInt(selection.options['3'].stake) >= this.selectedDrawGame.baseAmount))
        ) {
          this.selectionIsValid = true;
        } else {
          this.selectionIsValid = false;
          break;
        }
      } else {
        if (
          selection.stake &&
          !Number.isNaN(parseInt(selection.stake)) &&
          parseInt(selection.stake) >= this.selectedDrawGame.baseAmount
        ) {
          if (
            this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Mariage &&
            selection.numbers.first &&
            selection.numbers.second &&
            selection.numbers.first.length === this.padLength &&
            selection.numbers.second.length === this.padLength &&
            !Number.isNaN(parseInt(selection.numbers.first)) &&
            !Number.isNaN(parseInt(selection.numbers.second)) &&
            parseInt(selection.numbers.first) >= 0 &&
            parseInt(selection.numbers.second) >= 0
          ) {
            this.selectionIsValid = true;
          } else if (
            this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto6 &&
            selection.numbers.first &&
            selection.numbers.second &&
            selection.numbers.third &&
            selection.numbers.first.length === this.padLength &&
            selection.numbers.second.length === this.padLength &&
            selection.numbers.third.length === this.padLength &&
            !Number.isNaN(parseInt(selection.numbers.first)) &&
            !Number.isNaN(parseInt(selection.numbers.second)) &&
            !Number.isNaN(parseInt(selection.numbers.third)) &&
            parseInt(selection.numbers.first) >= 0 &&
            parseInt(selection.numbers.second) >= 0 &&
            parseInt(selection.numbers.third) >= 0
          ) {
            this.selectionIsValid = true;
          } else if (
            this.selectedDrawGame.betTypeId !== DrawGameBorletteBetType.Mariage &&
            this.selectedDrawGame.betTypeId !== DrawGameBorletteBetType.Loto6 &&
            selection.number &&
            selection.number.length === this.padLength &&
            !Number.isNaN(parseInt(selection.number)) &&
            parseInt(selection.number) >= 0
          ) {
            this.selectionIsValid = true;
          } else {
            this.selectionIsValid = false;
            break;
          }
        } else {
          this.selectionIsValid = false;
          break;
        }
      }
    }
    this.cdRef.markForCheck();
  }

  addToBetslip(fromModal = false) {
    this.isSelectionValid();
    if (this.selectionIsValid || fromModal) {
      let selection = fromModal ? this.selectionModal : this.selection;
      let selectedDrawGame = fromModal ? this.selectedDrawGameModal : this.selectedDrawGame;
      if (
        selectedDrawGame.betTypeId !== DrawGameBorletteBetType.Loto4 &&
        selectedDrawGame.betTypeId !== DrawGameBorletteBetType.Loto5
      ) {
        selection.forEach(item => {
          const betLine = this.createDrawGameBetLine(item, fromModal);
          this.betSlipService.addBetLine(betLine);
        });
      } else {
        selection.forEach(item => {
          for (const optionItem in item.options) {
            if (!item.options[optionItem].selected || !item.options[optionItem].stake) {
              continue;
            }
            const betLine = this.createDrawGameBetLineOption(
              item,
              item.options[optionItem].stake,
              optionItem,
              fromModal
            );
            this.betSlipService.addBetLine(betLine);
          }
        });
      }

      this.resetSelection();
      this.totalStake = 0;

      if (isPlatformBrowser(this.platformId)) {
        window.scroll({
          top: 0,
          left: 0,
          behavior: 'smooth'
        });
      }
    }
    this.isSelectionValid();
  }

  createDrawGameBetLine(item: any, fromModal: boolean): BetLine {
    let currentEventBetType: EventBetType = fromModal
      ? { ...this.selectedDrawGameModal }
      : { ...this.selectedDrawGame };
    if (currentEventBetType) {
      const baseList =
        currentEventBetType.betTypeId === DrawGameBorletteBetType.Mariage
          ? [item.numbers.first + item.numbers.second]
          : currentEventBetType.betTypeId === DrawGameBorletteBetType.Loto6
          ? [item.numbers.first, item.numbers.second, item.numbers.third]
          : [item.number];
      currentEventBetType.baseAmount = item.stake;
      return createBetLineWithSelection(
        this.event,
        currentEventBetType,
        baseList,
        [],
        BetCategoryType.DrawGame,
        this.event.drawGameRule
      );
    }
  }

  createDrawGameBetLineOption(item: any, stake: number, optionNumber: string, fromModal: boolean): BetLine {
    let currentEventBetType: EventBetType = fromModal
      ? { ...this.selectedDrawGameModal }
      : { ...this.selectedDrawGame };
    if (currentEventBetType) {
      currentEventBetType.baseAmount = stake;
      return createBetLineWithSelection(
        this.event,
        currentEventBetType,
        [item.number],
        [],
        BetCategoryType.DrawGame,
        this.event.drawGameRule,
        null,
        null,
        undefined,
        undefined,
        undefined,
        +optionNumber
      );
    }
  }

  openAutoModal(drawGameBetType: DrawGameBorletteBetType.Loto4 | DrawGameBorletteBetType.Mariage) {
    if (this.borletteNumbers.length === 0) {
      return;
    }

    this.titleModal = TitleModal[DrawGameBorletteBetType[drawGameBetType]];
    this.selectedDrawGameModal = this.drawGamesList.find(item => item.betTypeId === drawGameBetType);
    this.selectionModal = [];
    if (drawGameBetType === DrawGameBorletteBetType.Loto4) {
      this.generateLoto4Numbers();
    } else {
      this.generateMariageNumbers();
    }
    this.displayModal = true;
    this.cdRef.markForCheck();
  }

  generateMariageNumbers() {
    this.borletteNumbers.map((firstNumber: string) => {
      this.borletteNumbers.map((secondNumber: string) => {
        if (
          !this.selectionModal.find(
            item =>
              (item.numbers.first === firstNumber && item.numbers.second === secondNumber) ||
              (item.numbers.first === secondNumber && item.numbers.second === firstNumber)
          )
        ) {
          this.selectionModal.push({
            numbers: {
              first: firstNumber,
              second: secondNumber
            },
            stake: null,
            selected: false,
            error: {
              stake: false
            }
          });
        }
      });
    });
  }

  generateLoto4Numbers() {
    this.borletteNumbers.map((firstNumber: string, index: number) => {
      this.borletteNumbers.map((secondNumber: string, _index: number) => {
        if (
          (firstNumber !== secondNumber || (firstNumber === secondNumber && index !== _index)) &&
          !this.selectionModal.find(item => item.number === firstNumber + secondNumber)
        ) {
          this.selectionModal.push({
            number: firstNumber + secondNumber,
            stake: null,
            selected: false,
            options: {
              '1': {
                stake: null,
                selected: false,
                error: null
              },
              '2': {
                stake: null,
                selected: false,
                error: null
              },
              '3': {
                stake: null,
                selected: false,
                error: null
              }
            },
            error: {
              stake: false
            }
          });
        }
      });
    });
  }

  confirmModal(selection: any) {
    this.selectionModal = selection;
    this.addToBetslip(true);
    this.displayModal = false;
  }

  openTchalaPopin() {
    this.messageService
      .sendComponentMessage(
        TchalaComponent,
        { isInSelectionMode: true, selectedNumbers: this.selection?.map(item => item.number) },
        {
          canBeDismissed: true,
          displayClose: false,
          className: 'tchala-popin'
        }
      )
      .closed.pipe(takeUntil(this.destroy$))
      .subscribe((numbers: string[]) => {
        if (numbers) {
          // Add new numbers to selection if they are not already present
          numbers.forEach((number, index) => {
            if (!this.selection.some(item => item.number === number)) {
              if (index === 0 && this.selection.length > 0) {
                this.selection[this.selection.length - 1].number = number;
              } else {
                let defaultObject = JSON.parse(JSON.stringify(DEFAULT_NUMBER_OBJECT));
                defaultObject.number = number;
                this.setDefaultStake(defaultObject);
                this.selection.push(defaultObject);
              }
            }
          });

          // Remove numbers from selection that are no longer in the numbers array
          this.selection = this.selection.filter(item => numbers.includes(item.number));

          this.isSelectionValid();
        }
      });
  }

  getDefaultStake(): number {
    return (
      this.operatorConfiguration.bettingConfiguration?.defaultCustomerBorletteStake || this.selectedDrawGame.baseAmount
    );
  }
}

export enum TitleModal {
  Twins = 'Twins',
  Loto4 = 'Loto4',
  Mariage = 'Mariage'
}
