import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  HostBinding,
  Input,
  OnInit,
  Output,
  Renderer2
} from '@angular/core';
import { Async, AsyncTrigger, DestroySubject } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { ContentService } from '@honoregaming/templating';
import { Media, MediaService } from '@honoregaming/ui';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-draw-games-tchala',
  templateUrl: './tchala.component.html',
  styleUrls: ['./tchala.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TchalaComponent extends DestroySubject implements OnInit {
  @HostBinding('class.selection-mode')
  @Input()
  isInSelectionMode: boolean = false;
  @Input() selectedNumbers: string[] = [];
  @Output() close = new EventEmitter<string[]>();

  content: string;
  style: string;
  loading = true;

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;
  public searchText: string;

  constructor(
    private contentService: ContentService,
    private cdRef: ChangeDetectorRef,
    private i18nService: I18nService,
    private renderer: Renderer2,
    private mediaService: MediaService
  ) {
    super();
  }

  @Async()
  loadContent() {
    this.contentService
      .getContent('tchala')
      .pipe(takeUntil(this.destroy$))
      .subscribe(resource => {
        this.content = resource.content;
        this.style = resource.style;
        this.cdRef.markForCheck();
        this.loading = false;
      });
  }

  ngOnInit() {
    this.loadContent();
  }

  filter(searchTerm: string) {
    let isNoResult = false;
    this.loading = false;

    searchTerm = searchTerm.toLowerCase();

    document.querySelectorAll('hg-raw-template table tbody tr').forEach((row: HTMLTableRowElement) => {
      let dreamCell = row.querySelector('.dream');
      let bgNumberCell = row.querySelector('.bg-number');

      if (dreamCell || bgNumberCell) {
        let dreamCellValue = dreamCell ? dreamCell.innerHTML.toLowerCase() : '';
        if (dreamCellValue.indexOf(searchTerm) !== -1 || bgNumberCell.innerHTML.indexOf(searchTerm) !== -1) {
          row.style.display = 'inline-table';
          isNoResult = true;
        } else {
          row.style.display = 'none';
        }
      }
    });

    const noResultElement = document.querySelector<HTMLElement>('.no-result');
    if (!noResultElement) {
      return;
    }

    if (!isNoResult) {
      noResultElement.style.display = 'inline-table';
    } else {
      noResultElement.style.display = 'none';
    }
  }

  onContentLoaded() {
    if (this.isInSelectionMode) {
      const selectedNumbers = this.selectedNumbers.filter(n => n);
      const allBgNumbersCells = document.querySelectorAll<HTMLElement>('.bg-number');

      document
        .querySelectorAll<HTMLTableRowElement>('hg-raw-template table tbody tr')
        .forEach((row: HTMLTableRowElement) => {
          let dreamCell = row.querySelector<HTMLElement>('.dream');
          let bgNumberCells = row.querySelectorAll<HTMLElement>('.bg-number');

          if (dreamCell) {
            this.setupDreamCell(dreamCell, row, allBgNumbersCells);
          }

          if (bgNumberCells?.length) {
            this.setupBgNumberCells(bgNumberCells, selectedNumbers);
          }
        });
    }
  }

  private setupDreamCell(dreamCell: HTMLElement, row: HTMLTableRowElement, allBgNumbersCells: NodeListOf<HTMLElement>) {
    this.renderer.setStyle(dreamCell, 'cursor', 'pointer');

    if (this.mediaService.media < Media.md) {
      this.renderer.setStyle(dreamCell, 'width', 'auto');
    }

    let rowBgNumberCells = row.querySelectorAll<HTMLElement>('.bg-number');

    dreamCell.addEventListener('click', () => {
      const allSelected = Array.from(rowBgNumberCells).every(bgNumberCell =>
        this.selectedNumbers.includes(bgNumberCell.innerHTML)
      );

      rowBgNumberCells.forEach(bgNumberCell => {
        if (bgNumberCell) {
          if (allSelected) {
            this.toggleNumberSelection(bgNumberCell, allBgNumbersCells);
          } else {
            this.selectNumber(bgNumberCell, allBgNumbersCells);
          }
        }
      });
    });
  }

  private setupBgNumberCells(bgNumberCells: NodeListOf<HTMLElement>, selectedNumbers: string[]) {
    bgNumberCells.forEach(bgNumberCell => {
      if (bgNumberCell) {
        this.renderer.setStyle(bgNumberCell, 'cursor', 'pointer');

        bgNumberCell.addEventListener('click', () => {
          this.toggleNumberSelection(bgNumberCell, document.querySelectorAll<HTMLElement>('.bg-number'));
        });

        if (bgNumberCell.innerHTML === selectedNumbers?.find(n => +n === +bgNumberCell.innerHTML)?.toString()) {
          this.changeCellStyle(true, bgNumberCell);
        }
      }
    });
  }

  private selectNumber(bgNumberCell: HTMLElement, allBgNumbersCells?: NodeListOf<HTMLElement>) {
    if (!this.selectedNumbers.includes(bgNumberCell.innerHTML)) {
      this.selectedNumbers.push(bgNumberCell.innerHTML);
    }
    this.changeCellStyle(true, bgNumberCell);

    if (allBgNumbersCells) {
      allBgNumbersCells.forEach(cell => {
        if (cell && cell.innerHTML === bgNumberCell.innerHTML) {
          this.changeCellStyle(true, cell);
        }
      });
    }
  }

  private toggleNumberSelection(bgNumberCell: HTMLElement, allBgNumbersCells?: NodeListOf<HTMLElement>) {
    if (this.selectedNumbers.includes(bgNumberCell.innerHTML)) {
      this.selectedNumbers = this.selectedNumbers.filter(num => num !== bgNumberCell.innerHTML);
      this.changeCellStyle(false, bgNumberCell);

      if (allBgNumbersCells) {
        allBgNumbersCells.forEach(cell => {
          if (cell && cell.innerHTML === bgNumberCell.innerHTML) {
            this.changeCellStyle(false, cell);
          }
        });
      }
    } else {
      this.selectedNumbers.push(bgNumberCell.innerHTML);
      this.changeCellStyle(true, bgNumberCell);

      if (allBgNumbersCells) {
        allBgNumbersCells.forEach(cell => {
          if (cell && cell.innerHTML === bgNumberCell.innerHTML) {
            this.changeCellStyle(true, cell);
          }
        });
      }
    }
  }

  changeCellStyle(selected: boolean, element: HTMLElement) {
    if (selected) {
      this.renderer.setStyle(element, 'background-color', '#817f7f');
    } else {
      this.renderer.setStyle(element, 'background-color', '#1F4875');
    }
  }

  canSave(): boolean {
    return this.isInSelectionMode && this.selectedNumbers?.filter(n => +n).length > 0;
  }

  save() {
    this.close.emit(this.selectedNumbers.filter(n => +n).map(n => n.toString()));
  }
}
