import { Component, ChangeDetectionStrategy, EventEmitter, Input, Output, OnInit, Inject } from '@angular/core';
import { EventBetType, DrawGameBorletteBetType, BetCategoryType, DrawGame } from '@honoregaming/types';
import { TitleModal } from '../draw-game-borlette.component';
import { BetLine, BetSlipService, createBetLineWithSelection } from '@honoregaming/betslip';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { add, sub, mod } from '@honoregaming/core';

@Component({
  selector: 'hg-draw-game-borlette-modal',
  templateUrl: './draw-game-borlette-modal.component.html',
  styleUrls: ['./draw-game-borlette-modal.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DrawGameBorletteModalComponent implements OnInit {
  @Input() predefinedStakes: number[];
  @Input() selection: any[];
  @Input() numbers: string[] = [];
  @Input() selectedDrawGame: EventBetType;
  @Input() titleModal: TitleModal;
  @Input() event!: DrawGame;

  indexItemFocused: number;
  globalStake: number;
  globalStakeSelected: boolean = false;
  selectedNumbers: number = 0;
  totalStake: number = 0;
  selectionIsValid: boolean = false;
  TitleModal = TitleModal;
  defaultStake: number = 1;

  @Output() close: EventEmitter<void> = new EventEmitter<void>();

  @Output()
  confirmEvent = new EventEmitter();

  constructor(
    private betSlipService: BetSlipService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {}

  ngOnInit(): void {
    if (this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto4) {
      this.generateLoto4Numbers();
    } else {
      this.generateMariageNumbers();
    }

    // TODO : manage userScope when refacto for agent and customer
    this.defaultStake =
      this.operatorConfiguration.bettingConfiguration?.defaultCustomerBorletteStake ?? this.selectedDrawGame.baseAmount;
  }

  setFocusedItem(index: number): void {
    this.indexItemFocused = index;
  }

  decrement() {
    if (this.globalStake === this.selectedDrawGame.baseAmount) {
      return;
    }

    this.globalStake =
      !this.globalStake ||
      sub(this.globalStake, this.selectedDrawGame.minimumAmountIncrement) < this.selectedDrawGame.baseAmount
        ? this.selectedDrawGame.baseAmount
        : sub(this.globalStake, this.selectedDrawGame.minimumAmountIncrement);

    this.setGlobalStakeToItem(true);
  }

  increment(): void {
    this.globalStake = !this.globalStake
      ? this.defaultStake
      : add(this.globalStake, this.selectedDrawGame.minimumAmountIncrement);

    this.setGlobalStakeToItem(true);
  }

  setStake(amount: number): void {
    this.globalStake = amount;
    this.setGlobalStakeToItem(true);
  }

  setGlobalStakeToItem(selected = false) {
    if (this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto4) {
      this.selection.map(item => {
        item.options['1'].stake = this.globalStake;
        item.options['1'].selected = selected;
        item.options['2'].stake = this.globalStake;
        item.options['2'].selected = selected;
        item.options['3'].stake = this.globalStake;
        item.options['3'].selected = selected;
      });
    } else {
      this.selection.map(item => {
        item.stake = this.globalStake;
        item.selected = selected;
      });
    }
    this.globalStakeSelected = selected;
    this.selection = [...this.selection];
    this.computeTotalStake();
    this.computeSelectedNumbers();
  }

  resetStake(): void {
    this.globalStake = null;
    this.globalStakeSelected = false;
    if (this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto4) {
      this.selection.map(item => {
        item.options['1'].selected = false;
        item.options['1'].stake = null;
        item.options['2'].selected = false;
        item.options['2'].stake = null;
        item.options['3'].selected = false;
        item.options['3'].stake = null;
      });
    } else {
      this.selection.map(item => {
        item.stake = null;
        item.selected = false;
      });
    }

    this.setGlobalStakeToItem();
    this.computeSelectedNumbers();
    this.computeTotalStake();
  }

  changeStake(): void {
    if (!this.globalStake || this.globalStake < this.selectedDrawGame.baseAmount) {
      this.resetStake();
    }
    this.setGlobalStakeToItem(!!this.globalStake);
  }

  changeStakeItem(value: number, index: number): void {
    this.selection[index].stake = value;
    this.globalStakeSelected =
      this.selection.filter(item => item.selected && item.stake === this.globalStake).length === this.selection.length;
    if (
      this.selection[index].stake !== null &&
      this.selection[index].stake.toString().length > 0 &&
      this.selection[index].stake < this.selectedDrawGame.baseAmount
    ) {
      this.selection[index].selected = false;
      this.selection[index].error.stake = 'baseAmount';
      return;
    } else if (mod(this.selection[index].stake, this.selectedDrawGame.minimumAmountIncrement) !== 0) {
      this.selection[index].selected = false;
      this.selection[index].error.stake = 'minimumAmountIncrement';
      return;
    } else if (!this.selection[index].stake) {
      this.selection[index].selected = false;
    }

    this.selection[index].error.stake = false;
    this.selection[index].selected = true;
    this.computeSelectedNumbers();
    this.computeTotalStake();
  }

  changeStakeOptionsChange(data: { index: number; optionsIndex: string; value: number }, index: number) {
    this.selection[index].options[data.optionsIndex].stake = data.value;
    if (
      this.selection[index].options[data.optionsIndex].stake !== null &&
      this.selection[index].options[data.optionsIndex].stake.toString().length > 0 &&
      parseInt(this.selection[index].options[data.optionsIndex].stake) < this.selectedDrawGame.baseAmount
    ) {
      this.selection[index].options[data.optionsIndex].error = 'baseAmount';
      this.selection[index].options[data.optionsIndex].selected = false;
      this.checkGlobalStakeSelected();
      this.computeSelectedNumbers();
      this.computeTotalStake();
      return;
    } else if (parseInt(this.selection[index].options[data.optionsIndex].stake) >= this.selectedDrawGame.baseAmount) {
      this.selection[index].options[data.optionsIndex].selected = true;
    } else {
      this.selection[index].options[data.optionsIndex].selected = false;
    }
    this.selection[index].options[data.optionsIndex].error = false;

    if (this.selection[index].options[data.optionsIndex].selected) {
      if (
        mod(this.selection[index].options[data.optionsIndex].stake, this.selectedDrawGame.minimumAmountIncrement) !== 0
      ) {
        this.selection[index].options[data.optionsIndex].error = 'minimumAmountIncrement';
      }
      this.computeSelectedNumbers();
      this.computeTotalStake();
    } else {
      this.computeSelectedNumbers();
      this.computeTotalStake();
    }
    this.checkGlobalStakeSelected();
  }

  setStakeItem(amount: number, index: number): void {
    if (this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto4) {
      Object.entries(this.selection[index].options).forEach((option: any) => {
        option[1].stake = amount;
        option[1].selected = true;
      });
      this.checkGlobalStakeSelected();
    } else {
      this.selection[index].stake = amount;
      this.selection[index].selected = true;
      this.globalStakeSelected =
        this.selection.filter(item => item.selected && item.stake === this.globalStake).length ===
        this.selection.length;
    }
    this.computeTotalStake();
    this.computeSelectedNumbers();
  }

  resetStakeItem(index: number): void {
    if (this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto4) {
      Object.entries(this.selection[index].options).forEach((option: any) => {
        option[1].stake = null;
        option[1].selected = false;
      });
    } else {
      this.selection[index].stake = null;
      this.selection[index].selected = false;
    }
    this.globalStakeSelected = false;
    this.computeSelectedNumbers();
    this.computeTotalStake();
  }

  incrementStakeItem(index: number): void {
    this.selection[index].stake = +this.selection[index].stake;
    if (!this.selection[index].stake) {
      this.selection[index].stake = this.defaultStake;
      this.selection[index].selected = true;
      this.selection[index].error.stake = false;
      this.globalStakeSelected =
        this.selection.filter(item => item.selected && item.stake === this.globalStake).length ===
        this.selection.length;
      this.computeTotalStake();
      this.computeSelectedNumbers();
      return;
    }

    this.selection[index].stake = add(this.selection[index].stake, this.selectedDrawGame.minimumAmountIncrement);
    this.selection[index].selected = true;
    this.selection[index].error.stake = false;
    this.globalStakeSelected =
      this.selection.filter(item => item.selected && item.stake === this.globalStake).length === this.selection.length;
    this.computeTotalStake();
    this.computeSelectedNumbers();
  }

  decrementStakeItem(index: number): void {
    if (
      !this.selection[index].stake ||
      sub(this.selection[index].stake, this.selectedDrawGame.minimumAmountIncrement) < this.selectedDrawGame.baseAmount
    ) {
      this.selection[index].stake = !this.selection[index].stake ? this.defaultStake : this.selectedDrawGame.baseAmount;
      this.globalStakeSelected =
        this.selection.filter(item => item.selected && item.stake === this.globalStake).length ===
        this.selection.length;
      this.selection[index].selected = true;
      this.selection[index].error.stake = false;
      this.computeTotalStake();
      this.computeSelectedNumbers();
      return;
    }

    if (this.selection[index].stake === this.selectedDrawGame.baseAmount) {
      return;
    }

    this.selection[index].stake = sub(this.selection[index].stake, this.selectedDrawGame.minimumAmountIncrement);
    this.selection[index].error.stake = false;
    this.selection[index].selected = true;
    this.globalStakeSelected =
      this.selection.filter(item => item.selected && item.stake === this.globalStake).length === this.selection.length;
    this.computeTotalStake();
    this.computeSelectedNumbers();
  }

  handleDecrementOptionsItem(index: number, optionsIndex: string) {
    if (
      !this.selection[index].options[optionsIndex].stake ||
      sub(this.selection[index].options[optionsIndex].stake, this.selectedDrawGame.minimumAmountIncrement) <
        this.selectedDrawGame.baseAmount
    ) {
      this.selection[index].options[optionsIndex].stake = !this.selection[index].options[optionsIndex].stake
        ? this.defaultStake
        : this.selectedDrawGame.baseAmount;
      this.selection[index].options[optionsIndex].selected = true;
      this.checkGlobalStakeSelected();
      this.computeTotalStake();
      this.computeSelectedNumbers();
      this.selection[index].options[optionsIndex].error = false;
      return;
    }

    if (this.selection[index].options[optionsIndex].stake === this.selectedDrawGame.baseAmount) {
      return;
    }

    this.selection[index].options[optionsIndex].stake = sub(
      this.selection[index].options[optionsIndex].stake,
      this.selectedDrawGame.minimumAmountIncrement
    );
    this.checkGlobalStakeSelected();
    this.computeTotalStake();
    this.computeSelectedNumbers();
    this.selection[index].options[optionsIndex].error = false;
  }

  handleIncrementOptionsItem(index: number, optionsIndex: string) {
    this.selection[index].options[optionsIndex].stake = +this.selection[index].options[optionsIndex].stake;
    if (!this.selection[index].options[optionsIndex].stake) {
      this.selection[index].options[optionsIndex].stake = this.defaultStake;
      this.selection[index].options[optionsIndex].selected = true;
      this.checkGlobalStakeSelected();
      this.computeTotalStake();
      this.computeSelectedNumbers();
      this.selection[index].options[optionsIndex].error = false;
      return;
    }

    this.selection[index].options[optionsIndex].stake = add(
      this.selection[index].options[optionsIndex].stake,
      this.selectedDrawGame.minimumAmountIncrement
    );
    this.selection[index].options[optionsIndex].selected = true;
    this.checkGlobalStakeSelected();
    this.computeTotalStake();
    this.computeSelectedNumbers();
    this.selection[index].options[optionsIndex].error = false;
  }

  selectGlobalStake(): void {
    if (!this.globalStake) {
      return;
    }
    this.globalStakeSelected = !this.globalStakeSelected;

    if (this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto4) {
      this.selection.map(item => {
        item.options['1'].selected = this.globalStakeSelected;
        item.options['2'].selected = this.globalStakeSelected;
        item.options['3'].selected = this.globalStakeSelected;
      });
    } else {
      this.selection.map(item => {
        item.selected = this.globalStakeSelected;
      });
    }

    this.selection = [...this.selection];
    this.computeSelectedNumbers();
    this.computeTotalStake();
  }

  computeSelectedNumbers(): void {
    if (this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto4) {
      this.selectedNumbers = this.selection.filter(
        item => item.options['1'].selected || item.options['2'].selected || item.options['3'].selected
      ).length;
    } else {
      this.selectedNumbers = this.selection.filter(
        item => item.selected && item.stake && item.stake >= this.selectedDrawGame.baseAmount
      ).length;
    }

    this.isSelectionValid();
  }

  selectItem(index: number): void {
    this.selection[index].selected = !this.selection[index].selected;
    this.computeSelectedNumbers();
    this.computeTotalStake();
    this.globalStakeSelected =
      this.selection.filter(item => item.selected && item.stake === this.globalStake).length === this.selection.length;
  }

  selectOptionsItem(index: number, optionsIndex: string): void {
    this.selection[index].options[optionsIndex].selected = !this.selection[index].options[optionsIndex].selected;
    this.computeSelectedNumbers();
    this.computeTotalStake();
  }

  computeTotalStake(): void {
    this.totalStake = 0;

    if (this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto4) {
      this.selection.map(item => {
        this.totalStake = add(
          this.totalStake,
          item.options['1'].stake && item.options['1'].selected ? +item.options['1'].stake : 0
        );
        this.totalStake = add(
          this.totalStake,
          item.options['2'].stake && item.options['2'].selected ? +item.options['2'].stake : 0
        );
        this.totalStake = add(
          this.totalStake,
          item.options['3'].stake && item.options['3'].selected ? +item.options['3'].stake : 0
        );
      });
    } else {
      this.selection.forEach(item => {
        if (item.stake && item.selected) {
          this.totalStake = add(this.totalStake, +item.stake);
        }
      });
    }
  }

  isSelectionValid(): void {
    if (this.selectedNumbers === 0) {
      this.selectionIsValid = false;
      return;
    }

    this.selectionIsValid = true;
  }

  addToBetslip() {
    if (!this.selectionIsValid) {
      return;
    }

    const selectionToAdd =
      this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto4
        ? this.selection.filter(
            item => item.options['1'].selected || item.options['2'].selected || item.options['3'].selected
          )
        : this.selection.filter(item => item.selected && item.stake && item.stake >= this.selectedDrawGame.baseAmount);

    if (this.selectedDrawGame.betTypeId === DrawGameBorletteBetType.Loto4) {
      selectionToAdd.forEach(item => {
        for (const optionItem in item.options) {
          if (!item.options[optionItem].selected || !item.options[optionItem].stake) {
            continue;
          }
          const betLine = this.createLoto4BetLine(item, item.options[optionItem].stake, optionItem);
          this.betSlipService.addBetLine(betLine);
        }
      });
    } else {
      selectionToAdd.forEach(item => {
        const betLine = this.createMariageBetLine(item);
        this.betSlipService.addBetLine(betLine);
      });
    }

    this.close.emit();
  }

  createMariageBetLine(item: any): BetLine {
    let currentEventBetType: EventBetType = { ...this.selectedDrawGame };
    if (currentEventBetType) {
      const baseList =
        currentEventBetType.betTypeId === DrawGameBorletteBetType.Mariage
          ? [item.numbers.first + item.numbers.second]
          : currentEventBetType.betTypeId === DrawGameBorletteBetType.Loto6
          ? [item.numbers.first, item.numbers.second, item.numbers.third]
          : [item.number];
      currentEventBetType.baseAmount = item.stake;
      return createBetLineWithSelection(
        this.event,
        currentEventBetType,
        baseList,
        [],
        BetCategoryType.DrawGame,
        this.event.drawGameRule
      );
    }
  }

  createLoto4BetLine(item: any, stake: number, optionNumber: string): BetLine {
    let currentEventBetType: EventBetType = { ...this.selectedDrawGame };
    if (currentEventBetType) {
      currentEventBetType.baseAmount = stake;
      return createBetLineWithSelection(
        this.event,
        currentEventBetType,
        [item.number],
        [],
        BetCategoryType.DrawGame,
        this.event.drawGameRule,
        null,
        null,
        undefined,
        undefined,
        undefined,
        +optionNumber
      );
    }
  }

  checkGlobalStakeSelected(): void {
    let globalStakeSelected = true;
    this.selection.forEach(item => {
      Object.entries(item.options).forEach((option: any) => {
        if (option[1].stake !== this.globalStake || !option[1].selected) {
          globalStakeSelected = false;
        }
      });
    });
    this.globalStakeSelected = globalStakeSelected;
  }

  generateMariageNumbers() {
    this.selection = [];
    this.numbers.map((firstNumber: string) => {
      this.numbers.map((secondNumber: string) => {
        if (
          !this.selection.find(
            item =>
              (item.numbers.first === firstNumber && item.numbers.second === secondNumber) ||
              (item.numbers.first === secondNumber && item.numbers.second === firstNumber)
          )
        ) {
          this.selection.push({
            numbers: {
              first: firstNumber,
              second: secondNumber
            },
            stake: null,
            selected: false,
            error: {
              stake: false
            }
          });
        }
      });
    });
  }

  generateLoto4Numbers() {
    this.selection = [];
    this.numbers.map((firstNumber: string, index: number) => {
      this.numbers.map((secondNumber: string, _index: number) => {
        if (
          (firstNumber !== secondNumber || (firstNumber === secondNumber && index !== _index)) &&
          !this.selection.find(item => item.number === firstNumber + secondNumber)
        ) {
          this.selection.push({
            number: firstNumber + secondNumber,
            stake: null,
            selected: false,
            options: {
              '1': {
                stake: null,
                selected: false,
                error: null
              },
              '2': {
                stake: null,
                selected: false,
                error: null
              },
              '3': {
                stake: null,
                selected: false,
                error: null
              }
            },
            error: {
              stake: false
            }
          });
        }
      });
    });
  }
}
