import {
  Component,
  ChangeDetectorRef,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  ElementRef,
  ViewChild
} from '@angular/core';
import { takeUntil } from 'rxjs/operators';
import { BetLine, BetSlipService, computeAmountForDrawGames, createBetLineWithSelection } from '@honoregaming/betslip';
import { DestroySubject, shuffleArray, add, sub } from '@honoregaming/core';
import { AskQuestionComponent } from '@honoregaming/customer-ui';
import { I18nService } from '@honoregaming/i18n';
import { MessageService } from '@honoregaming/ui';
import { BetCategoryType, DrawGame, EventBetType } from '@honoregaming/types';
import { DrawGameMultipleFlashComponent } from '../../multiple-flash/multiple-flash.component';
import { TelemetryService } from '@honoregaming/customer-core';

interface Grid {
  baseSelection: number[];
  extraSelection: number[];
  position: number;
  betTypeName?: string;
  amount?: number;
}

enum SelectionType {
  Base,
  Extra
}

@Component({
  selector: 'hg-draw-game-default',
  templateUrl: './draw-game-default.component.html',
  styleUrls: ['./draw-game-default.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DrawGameDefaultComponent extends DestroySubject implements OnInit {
  @Input() event: DrawGame;
  @Input() loading: boolean;
  @Input() error: boolean;

  hasSpecialBetTypes: boolean;
  betTypeOptions: { [id: number]: string[] } = [];
  SelectionType = SelectionType;
  selectionIsValid: boolean;
  grids: Grid[] = [];
  gridOptions = [1, 3, 5, 10];
  currentGrid: Grid;
  currentGridOption: number;
  selectionBaseNumbers: number[] = [];
  selectionExtraNumbers: number[] = [];

  baseNumbers: number[] = [];
  extraNumbers: number[] = [];
  multipleFlashNumbers: number[] = [];
  totalStake: number = 0;

  @ViewChild('currentGridElement') currentGridElement: ElementRef;

  constructor(
    private cdRef: ChangeDetectorRef,
    private messageService: MessageService,
    private i18nService: I18nService,
    private betSlipService: BetSlipService,
    private telemetryService: TelemetryService
  ) {
    super();
  }

  ngOnInit(): void {
    this.setEvent(this.event);
    this.grids[0] = { baseSelection: [], extraSelection: [], position: 1, betTypeName: null };
    this.currentGrid = this.grids[0];
    this.currentGridOption = 1;
  }

  setEvent(event: DrawGame) {
    this.baseNumbers = Array.from(Array(this.event.drawGameRule.maxBaseNumber), (_d, i) => i + 1);
    if (event.drawGameRule.drawnExtraNumberCount) {
      this.extraNumbers = Array.from(Array(this.event.drawGameRule.maxExtraNumber), (_d, i) => i + 1);
    }
    this.selectionBaseNumbers = Array.from(Array(this.event.drawGameRule.drawnBaseNumberCount), (_d, i) => i);
    this.selectionExtraNumbers = Array.from(Array(this.event.drawGameRule.drawnExtraNumberCount ?? 0), (_d, i) => i);

    if (event.drawGameRule.drawGameDetails) {
      if (event.drawGameRule.drawGameDetails.length === 1) {
        this.hasSpecialBetTypes = false;
      } else {
        // if event has multiple bettypes
        event.drawGameRule.drawGameDetails.forEach(dgd => {
          if (!this.betTypeOptions[dgd.selectionCount]) {
            this.betTypeOptions[dgd.selectionCount] = [];
          }

          if (event.eventBetTypes) {
            this.betTypeOptions[dgd.selectionCount].push(
              event.eventBetTypes.find(ebt => ebt.betTypeId === dgd.betTypeId).name
            );
          }
        });
        this.hasSpecialBetTypes = true;
      }
    }

    for (let i = event.drawGameRule.minBaseSelection; i <= event.drawGameRule.maxBaseSelection; i++) {
      this.multipleFlashNumbers.push(i);
    }
  }

  isSelectionValid() {
    this.selectionIsValid = this.grids.length > 0;
    this.grids.forEach(grid => {
      if (
        grid.baseSelection.length < this.event.drawGameRule.minBaseSelection ||
        (this.event.drawGameRule.extraNumberEnabled &&
          grid.extraSelection.length < this.event.drawGameRule.minExtraSelection)
      ) {
        this.selectionIsValid = false;
      }
    });
  }

  addToBetslip() {
    this.isSelectionValid();
    if (this.selectionIsValid) {
      this.grids.forEach(grid => {
        const betLine = this.createDrawGameBetLine(grid);
        this.betSlipService.addBetLine(betLine);
      });

      this.grids = [];
      this.currentGrid = null;
      this.currentGridOption = 0;
      this.totalStake = 0;
    }
    this.isSelectionValid();
  }

  createDrawGameBetLine(grid: Grid): BetLine {
    let currentEventBetType: EventBetType;
    // get eventBettypeId for the current selection number/special betType
    if (this.hasSpecialBetTypes) {
      if (this.betTypeOptions[grid.baseSelection.length].length === 1) {
        currentEventBetType = this.event.eventBetTypes?.find(
          ebt => ebt.name === this.betTypeOptions[grid.baseSelection.length][0]
        );
      } else {
        currentEventBetType = this.event.eventBetTypes?.find(ebt => ebt.name === grid.betTypeName);
      }
    } else {
      currentEventBetType = this.event.eventBetTypes[0];
    }

    if (currentEventBetType) {
      return createBetLineWithSelection(
        this.event,
        currentEventBetType,
        grid.baseSelection.map(i => i.toString()),
        grid.extraSelection.map(i => i.toString()),
        BetCategoryType.DrawGame,
        this.event.drawGameRule
      );
    }
  }

  switchGrid(grid: Grid) {
    this.currentGrid = grid;
    this.isSelectionValid();
  }

  flash(grid: Grid, fromInterface: boolean, flashNumber: number = 3) {
    grid.baseSelection = shuffleArray([...this.baseNumbers])
      .slice(0, Math.max(this.event.drawGameRule.drawnBaseNumberCount, flashNumber))
      .sort((a, b) => a - b);

    if (this.event.drawGameRule.extraNumberEnabled) {
      grid.extraSelection = shuffleArray([...this.extraNumbers])
        .slice(0, this.event.drawGameRule.drawnExtraNumberCount)
        .sort((a, b) => a - b);
    }

    const betLine = this.createDrawGameBetLine(grid);
    const amount = computeAmountForDrawGames(betLine);
    grid.amount = amount.amount;
    this.cdRef.markForCheck();

    this.computeTotalStake();

    this.isSelectionValid();

    if (fromInterface) {
      this.telemetryService.trackEvent('draw_game_flash_individual', { grid_id: grid.position });
    }
  }

  flashAll() {
    this.telemetryService.trackEvent('draw_game_flash_main', { category: 'selection' });

    this.totalStake = 0;

    this.grids.forEach(grid => {
      this.flash(grid, false);
    });

    this.isSelectionValid();
  }

  eraseAll() {
    this.grids.forEach(grid => {
      grid.baseSelection = [];
      grid.extraSelection = [];
      grid.amount = null;
    });

    this.totalStake = 0;

    this.isSelectionValid();

    this.telemetryService.trackEvent('draw_game_clear_all', { action: 'reset' });
  }

  erase(grid: Grid) {
    this.totalStake = sub(this.totalStake, grid.amount);

    grid.baseSelection = [];
    grid.extraSelection = [];
    grid.amount = null;

    this.isSelectionValid();

    this.telemetryService.trackEvent('draw_game_clear_individual', { grid_id: grid.position });
  }

  deleteGrid(grid: Grid) {
    this.totalStake = sub(this.totalStake, grid.amount);

    if (grid === this.currentGrid) {
      this.currentGrid = null;
    }

    this.grids.splice(this.grids.indexOf(grid), 1);
    this.grids
      .filter(g => g.position > grid.position)
      .forEach(g => {
        g.position -= 1;
      });

    this.currentGridOption = this.grids.length;
    this.isSelectionValid();

    this.telemetryService.trackEvent('draw_game_delete', { grid_id: grid.position });
  }

  openMultipleFlashPopin() {
    if (this.currentGrid) {
      this.messageService
        .sendComponentMessage(DrawGameMultipleFlashComponent, {
          multipleFlashNumbers: this.multipleFlashNumbers
        })
        .closed.subscribe(result => {
          if (result) {
            this.telemetryService.trackEvent('draw_game_flash_multiple', { category: 'selection' });
            this.flash(this.currentGrid, true, result.flashNumber);
            this.cdRef.markForCheck();
          }
        });
    }
  }

  addGrid() {
    this.grids.push({
      baseSelection: [],
      extraSelection: [],
      position: this.grids.length + 1,
      betTypeName: null
    });

    this.currentGridOption = this.grids.length;
    this.isSelectionValid();
    this.currentGrid = this.grids[this.grids.length - 1];

    this.telemetryService.trackEvent('draw_game_add_grid', { total_grids: this.grids.length });
  }

  onGridOptionChange() {
    this.telemetryService.trackEvent('draw_game_grid_count_select', { value: this.currentGridOption });

    const difference = this.currentGridOption - this.grids.length;

    if (difference < 0 && this.grids.some(g => g.baseSelection?.length > 0)) {
      this.messageService
        .sendComponentMessage(AskQuestionComponent, {
          title: this.i18nService.translateSync('DRAW_GAMES.SELECTION_ACTIVE.TITLE'),
          text: this.i18nService.translateSync('DRAW_GAMES.SELECTION_ACTIVE.TEXT')
        })
        .closed.pipe(takeUntil(this.destroy$))
        .subscribe(result => {
          if (!!result?.success) {
            this.grids = [];
            this.grids[0] = { baseSelection: [], extraSelection: [], position: 1, betTypeName: null };
            this.currentGrid = this.grids[0];
            this.computeTotalStake();
            this.isSelectionValid();
          } else {
            this.currentGridOption = this.grids.length;
          }
        });
    } else {
      for (let i = 0; i < difference; i++) {
        this.addGrid();
      }

      while (this.currentGridOption < this.grids.length) {
        this.grids.pop();
      }
    }
  }

  onNumberClick(selectionType: SelectionType, number: number) {
    if (selectionType === SelectionType.Base) {
      if (
        this.grids.find(g => g.position === this.currentGrid.position)?.baseSelection.indexOf(number) === -1 &&
        this.grids.find(g => g.position === this.currentGrid.position)?.baseSelection.length <
          this.event.drawGameRule.maxBaseSelection
      ) {
        this.grids.find(g => g.position === this.currentGrid.position)?.baseSelection.push(number);
      } else if (this.grids.find(g => g.position === this.currentGrid.position)?.baseSelection.indexOf(number) > -1) {
        this.grids
          .find(g => g.position === this.currentGrid.position)
          ?.baseSelection.splice(
            this.grids.find(g => g.position === this.currentGrid.position).baseSelection.indexOf(number),
            1
          );
      }

      this.grids.find(g => g.position === this.currentGrid.position).baseSelection.sort((a, b) => a - b);
    } else if (selectionType === SelectionType.Extra) {
      if (
        this.grids.find(g => g.position === this.currentGrid.position).extraSelection.indexOf(number) === -1 &&
        this.grids.find(g => g.position === this.currentGrid.position).extraSelection.length <
          this.event.drawGameRule.maxExtraSelection
      ) {
        this.grids.find(g => g.position === this.currentGrid.position).extraSelection.push(number);
      } else if (this.grids.find(g => g.position === this.currentGrid.position).extraSelection.indexOf(number) > -1) {
        this.grids
          .find(g => g.position === this.currentGrid.position)
          .extraSelection.splice(
            this.grids.find(g => g.position === this.currentGrid.position).extraSelection.indexOf(number),
            1
          );
      }

      this.grids.find(g => g.position === this.currentGrid.position).extraSelection.sort((a, b) => a - b);
    }

    // set or unset special bettype
    if (
      this.hasSpecialBetTypes &&
      this.betTypeOptions[this.currentGrid.baseSelection.length]?.length > 1 &&
      !this.currentGrid.betTypeName
    ) {
      this.currentGrid.betTypeName = this.betTypeOptions[this.currentGrid.baseSelection.length][0];
    } else {
      this.currentGrid.betTypeName = null;
    }

    const betLine = this.createDrawGameBetLine(this.currentGrid);
    const amount = computeAmountForDrawGames(betLine);
    this.currentGrid.amount = amount.amount;

    this.computeTotalStake();

    this.isSelectionValid();
  }

  computeTotalStake(): void {
    this.totalStake = 0;

    this.grids?.forEach(grid => {
      this.totalStake = add(this.totalStake, grid.amount);
    });
  }

  maxArray(number1: number, number2: number) {
    return Array.from(Array(Math.max(number1, number2)), (_d, i) => i);
  }
}
