import { Pipe, PipeTransform } from '@angular/core';

@Pipe({
  name: 'hgLongCountDownFormat'
})
export class LongCountDownFormatPipe implements PipeTransform {
  transform(valueInMs: number): string {
    const computedSeconds = Math.floor((valueInMs / 1000) % 60);
    const computedMinutes = Math.floor((valueInMs / (1000 * 60)) % 60);
    const computedHours = Math.floor(valueInMs / (1000 * 60 * 60));

    const hours = computedHours < 10 ? '0' + computedHours : computedHours;
    const minutes = computedMinutes < 10 ? '0' + computedMinutes : computedMinutes;
    const seconds = computedSeconds < 10 ? '0' + computedSeconds : computedSeconds;

    return hours + ' : ' + minutes + ' : ' + seconds;
  }
}
