import { trigger, transition, animate, style } from '@angular/animations';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  Inject,
  NgZone,
  OnDestroy,
  OnInit,
  PLATFORM_ID
} from '@angular/core';
import { ApplicationStateService, delayBetween, DestroySubject, getUtcNow } from '@honoregaming/core';
import { DrawGame } from '@honoregaming/types';
import { EventsService } from '@honoregaming/events';
import { takeUntil, finalize, take } from 'rxjs/operators';
import { isPlatformBrowser } from '@angular/common';
import { DrawGameBetSlipService } from '@honoregaming/betslip';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { DrawGamesService } from '@honoregaming/draw-games-ui';

@Component({
  selector: 'hg-draw-games-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  animations: [
    trigger('removed', [
      transition('* => void', [animate('0.1s ease-out', style({ transform: 'scale(0)', height: '0' }))])
    ])
  ]
})
export class HomeComponent extends DestroySubject implements OnInit, OnDestroy {
  private readonly DISPLAY_REPLAY_INFO_STORAGE_KEY = 'DrawGames_HomeComponent_displayReplayInfo';

  loading = false;
  oldEventsCleanTimer: any;
  selectedBets: { eventId: number; betTypeId: number; eventBetTypeItemId: number }[];
  events: DrawGame[] = [];
  error = false;
  displayReplayInfo: boolean = false;

  constructor(
    private eventsService: EventsService,
    private cdRef: ChangeDetectorRef,
    private zone: NgZone,
    @Inject(PLATFORM_ID) private platformId,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private appStateService: ApplicationStateService,
    private drawGameBetSlipService: DrawGameBetSlipService,
    private drawGamesService: DrawGamesService
  ) {
    super();
  }

  ngOnInit() {
    this.loading = true;
    this.loadEvents();
    this.drawGameBetSlipService.$drawGameBetPlaced
      .pipe(takeUntil(this.destroy$))
      .subscribe(_ => this.updateDisplayReplayInfo());
  }

  ngOnDestroy(): void {
    super.ngOnDestroy();

    if (this.oldEventsCleanTimer) {
      clearTimeout(this.oldEventsCleanTimer);
    }
  }

  loadEvents() {
    this.eventsService
      .getNextDrawGamesEvents()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        events => {
          this.events = this.drawGamesService.filterAndSortDrawGames(events);

          if (this.events?.length > 0 && isPlatformBrowser(this.platformId)) {
            this.appStateService.isReady$.pipe(take(1)).subscribe(() => {
              this.removeOldEvents();
            });
          }

          this.updateDisplayReplayInfo();
          this.drawGamesService.displayNextDrawGamesDates(this.events?.map(x => x.expectedStart));
        },
        _error => {
          this.error = true;
        }
      );
  }

  private removeOldEvents(): void {
    this.oldEventsCleanTimer = setTimeout(() => {
      if (this.oldEventsCleanTimer) {
        clearTimeout(this.oldEventsCleanTimer);
      }

      const expiredEventsIds = this.events.filter(ebt => new Date(ebt.expectedStart) <= getUtcNow()).map(x => x.id);
      if (expiredEventsIds.length) {
        this.events = this.events.filter(x => !expiredEventsIds.includes(x.id));
        this.zone.run(() => this.cdRef.markForCheck());
        this.loadEvents();
      }
    }, Math.min(1000, delayBetween(getUtcNow(), new Date(this.events[0].expectedStart))));
  }

  trackEvent(_index: number, event: DrawGame) {
    return event.id;
  }

  closeReplayInfo(): void {
    this.displayReplayInfo = false;
    sessionStorage.setItem(this.DISPLAY_REPLAY_INFO_STORAGE_KEY, String(this.displayReplayInfo));
  }

  updateDisplayReplayInfo(): void {
    this.displayReplayInfo =
      (this.events?.some(x =>
        this.drawGameBetSlipService.canReplayEvent(
          x,
          this.operatorConfiguration?.drawGameConfiguration?.allowsCustomerToReplayLastDrawGameSelection,
          this.events
        )
      ) ??
        false) &&
      !(sessionStorage.getItem(this.DISPLAY_REPLAY_INFO_STORAGE_KEY) === 'false');
  }
}
