import { HomeComponent } from './containers/home/home.component';
import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';
import { SidebarComponent } from './components/sidebar/sidebar.component';
import { LayoutComponent } from './containers/layout/layout.component';
import { DrawGameComponent } from './containers/draw-game/draw-game.component';
import { DrawGameResultsComponent } from './containers/results/results.component';
import { DrawGameRulesComponent } from './containers/rules/rules.component';
import { BetCategoriesGuard } from '@honoregaming/core';
import { BetCategoryType } from '@honoregaming/types';
import { DrawGamesPageHeaderComponent } from './components/draw-games-page-header/draw-games-page-header.component';

const routes: Routes = [
  {
    path: '',
    data: { betCategories: BetCategoryType.DrawGame },
    canLoad: [BetCategoriesGuard],
    component: LayoutComponent,
    children: [
      { path: '', component: HomeComponent },
      { path: 'results', component: DrawGameResultsComponent },
      { path: 'rules', component: DrawGameRulesComponent },
      { path: 'borlette', component: DrawGameComponent },
      { path: ':eventId', component: DrawGameComponent }
    ]
  },
  { path: '', outlet: 'sidebar', component: SidebarComponent },
  { path: '', outlet: 'subheader', component: DrawGamesPageHeaderComponent }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class HgDrawGamesRoutingModule {}
